	('cmvj9snu6002egxl0bbosorlr', 'cmvj9snpq000wgxl0pwj9nmhc', 3, 'WR-001_REV_001_FIELDS_ALIGNED', '2026-07-03 00:00:00', NULL, true, '2026-08-28 00:00:00', 'Warehouse Records - stock Releasing Form.xlsx', NULL, '{"title": "Warehouse Records - Stock Releasing Form", "sections": [{"key": "monitoringEntries", "items": [{"key": "releaseEntries", "type": "repeatable", "label": "Release Entries", "fields": [{"key": "customerName", "type": "text", "label": "Name of Customer", "required": true, "validation": {"maxLength": 256}}, {"key": "productSize", "type": "text", "label": "Product Size", "required": true, "validation": {"maxLength": 128}}, {"key": "quantity", "type": "number", "label": "Qty", "required": true, "validation": {"max": 999999999, "min": 0.000001, "step": 0.001}}, {"key": "uom", "type": "select", "label": "UOM", "options": [{"label": "PACK", "value": "PACK"}, {"label": "BOX", "value": "BOX"}, {"label": "CASE", "value": "CASE"}, {"label": "BAG", "value": "BAG"}, {"label": "KG", "value": "KG"}], "required": true}, {"key": "productionDate", "type": "date", "label": "Production Date", "required": true}, {"key": "consumeBeforeDate", "type": "trace-code", "label": "Consume Before Date", "helpText": "Connected directly to the matching Consume Before Code from Packing PPM.", "readOnly": true, "required": true, "placeholder": "Select the Packing Consume Before Code..."}, {"key": "timeReleased", "type": "time", "label": "Time Released", "required": true}, {"key": "poNumber", "type": "text", "label": "P.O No.", "required": true, "validation": {"maxLength": 128}}, {"key": "receiptNumber", "type": "text", "label": "Receipt No.", "required": true, "validation": {"maxLength": 128}}, {"key": "vehicleType", "type": "select", "label": "Vehicle Type", "options": [{"label": "Close", "value": "CLOSE"}, {"label": "Open", "value": "OPEN"}], "required": true}, {"key": "shipmentType", "type": "select", "label": "Shipment Type", "options": [{"label": "Delivery", "value": "DELIVERY"}, {"label": "Pick-up", "value": "PICK_UP"}], "required": true}, {"key": "driver", "type": "text", "label": "Driver", "required": true, "validation": {"maxLength": 256}}, {"key": "vehiclePlateNumber", "type": "text", "label": "Vehicle Plate No.", "required": true, "validation": {"maxLength": 64, "minLength": 2}}], "maxRows": 200, "minRows": 1, "required": true}], "label": "Stock Releasing Entries", "columns": 1, "description": "Add every customer stock release completed for this warehouse record."}], "description": "Controlled WR-001 stock releases connected directly to exact approved Packing outputs.", "schemaVersion": 1}', '2026-10-22 08:19:33.678', '2026-10-22 08:19:33.678', 'WR-001', '001', NULL, NULL),
